#!/bin/bash
# Print the three most frequent IPs in access.log, most frequent first,
# breaking ties by first appearance in the log.
set -eu

awk '
{
    ip = $1
    count[ip]++
    if (!(ip in seen)) {
        seen[ip] = ++order
    }
}
END {
    # Bucket sort by count (counts are small integers), preserving
    # first-appearance order within each count bucket.
    for (line = 1; ; line++) {
        printed = 0
        for (i = 1; i <= order; i++) {
            # recover the ip that got first-appearance order i
            for (ip in count) {
                if (seen[ip] == i) {
                    if (count[ip] == line) {
                        print ip
                        printed = 1
                        if (++total == 3) exit 2
                    }
                    break
                }
            }
        }
        if (total >= 3) exit 0
        if (!printed) break
    }
}' access.log

#!/bin/bash
# Print the three most frequent IPs in access.log, most frequent first,
# breaking ties by first appearance in the log.
set -eu

awk '
{
    ip = $1
    count[ip]++
    if (!(ip in seen)) {
        seen[ip] = ++order
        byOrder[order] = ip
        if (count[ip] > maxCount) maxCount = count[ip]
    }
}
END {
    for (c = maxCount; c >= 1 && printed < 3; c--)
        for (i = 1; i <= order && printed < 3; i++) {
            ip = byOrder[i]
            if (count[ip] == c) {
                print ip
                printed++
            }
        }
}' access.log

